def compute(vars):
    allowances = vars["v1"]
    receivables = vars["v2"]

    if receivables == 0:
        return None

    ratio = allowances / receivables
    percentage = round(ratio * 100, 3)

    return {
        "value": percentage,
        "trace": {
            "allowances_for_doubtful_accounts": allowances,
            "trade_and_other_accounts_receivable": receivables,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
